sql.where:
deleted = 0

    AND tenant_id = #{dto.tenantId, jdbcType=VARCHAR}


    AND id = #{dto.id, jdbcType=BIGINT}


    AND sku_code = #{dto.skuCode, jdbcType=VARCHAR}


    AND sku_name LIKE CONCAT('%', #{dto.skuName, jdbcType=VARCHAR}, '%')


    AND revision = #{dto.revision, jdbcType=VARCHAR}


    AND sku_type = #{dto.skuType, jdbcType=VARCHAR}


    AND saleable = #{dto.saleable, jdbcType=TINYINT}


    AND visible = #{dto.visible, jdbcType=TINYINT}


    AND is_current = #{dto.isCurrent, jdbcType=TINYINT}


    AND status = #{dto.status, jdbcType=VARCHAR}

mapper.select:
SELECT

FROM product_center.product_sku
WHERE deleted = 0
  AND tenant_id = #{tenantId, jdbcType=VARCHAR}
  AND sku_code = #{skuCode, jdbcType=VARCHAR}

      AND revision = #{skuRevision, jdbcType=VARCHAR}


      AND is_current = 1

LIMIT 1
